-- Fixed-width UTC text preserves chronological index order within a second.
UPDATE tasks SET next_run_at=substr(next_run_at,1,19)||'.'||substr((CASE WHEN substr(next_run_at,20,1)='.' THEN substr(next_run_at,21,length(next_run_at)-21) ELSE '' END)||'000000000',1,9)||'Z' WHERE next_run_at IS NOT NULL AND substr(next_run_at,-1)='Z';
UPDATE tasks SET last_run_at=substr(last_run_at,1,19)||'.'||substr((CASE WHEN substr(last_run_at,20,1)='.' THEN substr(last_run_at,21,length(last_run_at)-21) ELSE '' END)||'000000000',1,9)||'Z' WHERE last_run_at IS NOT NULL AND substr(last_run_at,-1)='Z';
